      "description": "`git check-ignore` tient aussi compte de `.git/info/exclude` et des exclusions globales. Après nettoyage de l'historique et de l'index, une exclusion provenant uniquement de ces sources valide donc l'étape sans aucune règle dans `.gitignore`, contrairement au critère demandé. Il faut vérifier la provenance de la règle applicable, pas seulement le code de retour de `check-ignore`.",
      "test_pytest": "from types import SimpleNamespace

from wavedevsecops.scenarios.steps import history_clean


def test_exclusion_locale_ne_remplace_pas_gitignore(tmp_path):
    exclude = tmp_path / '.git' / 'info' / 'exclude'
    exclude.parent.mkdir(parents=True)
    exclude.write_text('.env\n', encoding='utf-8')

    class FakeGit:
        def run(self, *args, **kwargs):
            assert kwargs['cwd'] == tmp_path
            assert args[0] == 'check-ignore'
            # Git trouve une exclusion, mais sa provenance n'est pas .gitignore.
            verbose = '-v' in args or '--verbose' in args
            if verbose:
                stdout = (
                    '.git/info/exclude\0' + '1\0.env\0.env\0'
                    if '-z' in args
                    else '.git/info/exclude:1:.env\t.env\n'
                )
            else:
                stdout = ''
            return SimpleNamespace(ok=True, returncode=0, stdout=stdout)

    git = FakeGit()
    ctx = SimpleNamespace(git=lambda: git, layout=SimpleNamespace(repo=tmp_path))
    assert history_clean._is_ignored(ctx, '.env') is False
